    frames=[]; boxes=[]
    for color in range(1,10):
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if not pts: continue
        r0=min(r for r,c in pts);r1=max(r for r,c in pts);c0=min(c for r,c in pts);c1=max(c for r,c in pts)
        if r1-r0>=2 and c1-c0>=2 and all(grid[r0][c]==color and grid[r1][c]==color for c in range(c0,c1+1)) and all(grid[r][c0]==color and grid[r][c1]==color for r in range(r0,r1+1)):
            frames.append((color,r0,r1,c0,c1)); boxes.append((r0,r1,c0,c1))
    # Preserve only frame lines. Fill every other interior square in alternating checker pattern.
    for color,r0,r1,c0,c1 in frames:
        for c in range(c0,c1+1): out[r0][c]=out[r1][c]=color
        for r in range(r0,r1+1): out[r][c0]=out[r][c1]=color
        # Demos show marker placed in checker positions is color of isolated 1-pixel cue;
        # choose nearest external non-frame pixel color to the frame.
        best=None
        for r in range(h):
            for c in range(w):
                v=grid[r][c]
                if not v or any(a<=r<=b and x<=c<=y for a,b,x,y in boxes): continue
                d=abs(r-(r0+r1)/2)+abs(c-(c0+c1)/2)
                if best is None or d<best[0]: best=(d,v)
        motif=best[1] if best else 0
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r-r0+c-c0)%2==0: out[r][c]=motif
